def build(target_dir: str = 'idbr_project') -> None:
    """Write every file in FILES out under target_dir, creating
    directories as needed."""
    for rel_path, b64_content in FILES.items():
        out_path = os.path.join(target_dir, rel_path)
        os.makedirs(os.path.dirname(out_path) or '.', exist_ok=True)
        data = base64.b64decode(b64_content) if b64_content else b''
        with open(out_path, 'wb') as f:
            f.write(data)
        print(f'wrote {out_path} ({len(data)} bytes)')
    print(f"\nProject written to '{target_dir}/'. "
          "cd into it, `pip install -r requirements.txt`, and run "
          "`python -m src.train` to start training.")


if __name__ == '__main__':
    target = sys.argv[1] if len(sys.argv) > 1 else 'idbr_project'
    build(target)
